// 여행담 기기 저장형 1.0.0. 서버·로그인·기존 사이트 데이터와는 별도입니다.
const $=s=>document.querySelector(s), esc=escapeHTML, clone=x=>JSON.parse(JSON.stringify(x));
const uid=()=>globalThis.crypto?.randomUUID?.()||`yd-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const BASE='https://kr.choiworks.yeohaengdam/';
const isNative=location.href.startsWith(BASE);
const icons={home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>',pack:'<path d="M8 6V4h8v2 M5 7h14v14H5Z M8 12l2 2 5-5 M9 18h6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4 M17 3v4 M3 10h18 M7 14h3 M14 14h3 M7 18h3"/>',plan:'<path d="M7 4h10a4 4 0 0 1 0 8H7a4 4 0 0 0 0 8h10"/><circle cx="6" cy="4" r="2"/><circle cx="18" cy="20" r="2"/>',during:'<path d="m3 10 18-7-7 18-3-8Z M11 13 21 3"/>',after:'<path d="M12 5v16 M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2Z"/>',report:'<path d="M6 3h9l4 4v14H6Z M14 3v5h5 M9 12h7 M9 16h7"/>',list:'<path d="M3 7V4h7l2 3h9v13H3Z M7 12h9 M7 16h6"/>',photo:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="9" cy="9" r="2"/><path d="m3 18 5-5 4 3 4-6 5 8"/>',edit:'<path d="m16 3 5 5-12 12-6 1 1-6Z M14 5l5 5"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Z M9 3v16 M15 5v16"/>',eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>'};
const icon=n=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.home}</svg>`;
const menus=[['main','메인화면','메인화면','home'],['packing','준비물 챙기기','준비물','pack'],['calendar','여행 달력','달력','calendar'],['plan','여행 계획 세우기','계획','plan'],['during','여행중','여행중','during'],['after','여행후','여행후','after'],['report','보고서','보고서','report'],['list','내가 그동안 다닌 여행목록','여행목록','list']];
const statusNames={planned:'예정',active:'여행중',done:'완료',skipped:'건너뜀'};
let db,state={schema:1,trips:[],currentId:null},photoMap=new Map(),view='main',chosenDate=todayISO(),commitTail=Promise.resolve(),modalCleanup=null,routeMode='places',recordDraftPhotos=[],mapCtl=null;
let dirtyForm=false,toastTimer,renderTicket=0;
function notify(text){const t=$('#toast');t.textContent=text;t.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>{t.hidden=true;},3300);}
function errorMessage(error){return error?.name==='QuotaExceededError'?'저장 공간이 부족합니다. 백업 후 불필요한 사진을 정리해 주세요.':error?.message||'작업을 완료하지 못했습니다. 다시 시도해 주세요.';}
const trip=()=>state.trips.find(t=>t.id===state.currentId&&!t.deletedAt)||null;
function safeURL(v){try{const u=new URL(v);return u.protocol==='https:'?u.href:'';}catch{return '';}}
function native(command,value=''){if(!isNative)return false;return window.prompt(command,value)==='ok';}
function openLink(url){url=safeURL(url);if(!url){notify('안전한 HTTPS 주소만 열 수 있습니다.');return;}if(isNative){native('YD_OPEN',url);}else{window.open(url,'_blank','noopener,noreferrer');}}
function openDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open('yeohaengdam-device-v1',1);q.onupgradeneeded=()=>{const d=q.result;d.createObjectStore('kv');d.createObjectStore('photos',{keyPath:'id'});};q.onerror=()=>reject(new Error('기기 저장소를 열 수 없습니다. 저장 공간과 앱 권한을 확인해 주세요.'));q.onsuccess=()=>resolve(q.result);});}
function dbGet(store,key){return new Promise((res,rej)=>{let t=db.transaction(store,'readonly'),q=t.objectStore(store).get(key);q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error);});}
function dbAll(store){return new Promise((res,rej)=>{let t=db.transaction(store,'readonly'),q=t.objectStore(store).getAll();q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error);});}
function dbWrite(s,photos=[]){return new Promise((res,rej)=>{const tx=db.transaction(['kv','photos'],'readwrite');tx.objectStore('kv').put(s,'state');for(const p of photos)tx.objectStore('photos').put(p);tx.oncomplete=res;tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error||new Error('저장이 취소되었습니다.'));});}
function commit(change){$('#save-status').textContent='저장 중…';const work=commitTail.catch(()=>{}).then(async()=>{const next=clone(state);change(next);await dbWrite(next);state=next;$('#save-status').textContent='✓ 기기에 저장됨';});commitTail=work;work.catch(e=>{$('#save-status').textContent='저장 실패';notify(errorMessage(e));});return work;}
const packingStorage={label:'이 앱에 저장',async load(id){await commitTail.catch(()=>{});return clone(state.trips.find(t=>t.id===id)?.packing||[]);},async save(id,items){await commit(s=>{const t=s.trips.find(t=>t.id===id);if(!t)throw new Error('여행을 찾을 수 없습니다.');t.packing=validatePacking(items);t.updatedAt=new Date().toISOString();});}};
function photo(id){return photoMap.get(id)||null;}
function photoHTML(id,cls='',alt='여행 사진'){let p=photo(id);return p?`<img class="${cls}" src="${p.data}" alt="${esc(alt)}" loading="lazy">`:'';}
function allDates(t){return Array.from({length:tripDays(t)},(_,i)=>addDays(t.startDate,i));}
function itemsOn(t,date,includeSkipped=true){return t.itinerary.filter(x=>x.date===date&&(includeSkipped||x.status!=='skipped')).sort((a,b)=>a.order-b.order||a.startTime.localeCompare(b.startTime));}
function primaryTitles(t,date){return titlesForDate(t.itinerary.map(x=>({...x,cancelled:x.status==='skipped'})),date);}
function dailyPhoto(t,date){return t.records.filter(r=>r.date===date).flatMap(r=>r.photoIds).find(id=>photo(id))||null;}
function routeFor(t,date){let arr=itemsOn(t,date,false);if(routeMode==='areas'){return [...new Set(arr.map(x=>x.area?.trim()||x.title))].join(' → ');}return primaryTitles(t,date).join(' → ');}
function navigate(next, date){view=next;if(date)chosenDate=date;let t=trip();if(t&&!inTrip(chosenDate,t))chosenDate=t.startDate;closeModal(true);render();window.scrollTo({top:0,behavior:'instant'});}
function renderNav(){for(const[id,short]of[['top-nav',false],['bottom-nav',true]]){const nav=$('#'+id),prev=nav.scrollLeft;nav.innerHTML=menus.map(([k,label,abbr,i])=>`<button data-go="${k}" aria-label="${label}" ${view===k?'aria-current="page"':''}>${icon(i)}<span>${short?abbr:label}</span></button>`).join('');nav.scrollLeft=prev;const current=nav.querySelector('[aria-current]');if(current){const x=current.offsetLeft-nav.offsetLeft;if(x<nav.scrollLeft)nav.scrollLeft=Math.max(0,x-9);else if(x+current.offsetWidth>nav.scrollLeft+nav.clientWidth)nav.scrollLeft=x+current.offsetWidth-nav.clientWidth+9;}}}
function heading(kicker,title,desc){return `<p class="eyebrow">${kicker}</p><h1 class="title">${title}</h1><p class="subtitle">${desc}</p>`;}
function noTrip(){return `<div class="empty"><div class="empty-icon">${icon('plan')}</div><h2>첫 여행을 시작해 볼까요?</h2><p>제목과 날짜를 정하면 준비물부터 달력,<br>여행 기록과 보고서까지 하나로 연결됩니다.</p><div class="actions" style="justify-content:center"><button class="btn primary" data-action="new">＋ 새 여행 만들기</button></div></div><div class="notice neutral gap-top">이 앱은 휴대폰에 직접 저장하는 독립 설치판입니다. 기존 여행담 웹사이트의 계정 기록과 자동 동기화하지 않습니다.</div>`;}
async function render(){const ticket=++renderTicket,t=trip();renderNav();const select=$('#trip-select');select.innerHTML=state.trips.filter(x=>!x.deletedAt).map(x=>`<option value="${x.id}" ${t?.id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')||'<option>나의 첫 여행</option>';select.disabled=!t;const tool=$('#trip-tools');tool.hidden=true;$('#view').hidden=false;
 if(['packing','calendar'].includes(view)&&t){$('#view').hidden=true;tool.hidden=false;tool.view=view;await tool.configure({trip:t,itinerary:t.itinerary.map(x=>({...x,cancelled:x.status==='skipped'})),scope:'device-v1',storage:packingStorage});return;}
 if(view==='list'){renderList();return;}if(view==='settings'){renderSettings();return;}if(!t){$('#view').innerHTML=noTrip();return;}
 if(view==='main')renderMain(t);else if(view==='plan'||view==='during')renderPlan(t);else if(view==='after')renderAfter(t);else if(view==='report')renderReport(t);
}
function renderMain(t){const days=tripDays(t),done=t.packing.filter(x=>x.checked).length;$('#view').innerHTML=`<section class="cover">${photoHTML(t.coverId,'cover-photo',t.title)}<div class="cover-decoration"></div><div class="cover-overlay"></div><div class="cover-content"><p class="eyebrow">MY OWN TRAVEL CHAPTER</p>${t.theme?`<span class="pill">${esc(t.theme)}</span>`:''}<h1 class="cover-title">${esc(t.title)}</h1><div class="cover-detail">${esc(t.destination||'나의 여행')} · ${days===1?'당일 여행':`${days-1}박 ${days}일`}<br>${esc(t.startDate)} — ${esc(t.endDate)}${t.people?`<br>${esc(t.people)}와 함께`:''}</div></div></section><div class="cover-controls"><button class="btn compact" data-action="edit-trip">${icon('edit')} 제목·여행 정보</button><button class="btn compact" data-action="cover">${icon('photo')} 내 사진 넣기</button><button class="btn compact" data-action="image-search">사진 검색</button></div>${attribution(photo(t.coverId))}${t.description?`<p class="subtitle">${esc(t.description)}</p>`:''}<div class="grid gap-top"><button class="quick-card" data-go="packing">${icon('pack')}<b>준비물 챙기기</b><span>${t.packing.length}개 중 ${done}개 준비 완료</span></button><button class="quick-card" data-go="calendar">${icon('calendar')}<b>여행 달력</b><span>${days}일의 여행을 한눈에</span></button></div><div class="split gap-top"><h2 style="font-size:20px;margin:0">매일의 여행 한 장</h2><button class="text-btn" data-action="route-mode">${routeMode==='places'?'지역 이동만 보기':'대표 일정으로 보기'}</button></div><p class="mini-text">일정을 바꾸면 날짜별 제목과 여행 사진이 자동으로 연결됩니다.</p><div class="stack">${allDates(t).map((date,i)=>`<article class="day-card"><div class="content"><span class="day-num">DAY ${String(i+1).padStart(2,'0')} · ${koreanDate(date)}</span><h3>${esc(routeFor(t,date)||'아직 등록된 일정이 없어요')}</h3><p>${itemsOn(t,date).length}개의 일정</p><div class="actions" style="margin-top:6px"><button class="text-btn" data-go="plan" data-date="${date}">일정·지도 보기 ↗</button><button class="text-btn" data-action="record" data-date="${date}">이날의 사진 넣기</button></div></div>${photoHTML(dailyPhoto(t,date),'day-photo')}</article>`).join('')}</div>`;}
function attribution(p){return p?.sourceURL?`<p class="attribution">사진 출처: <a href="${esc(safeURL(p.sourceURL))}">${esc(p.author||'Wikimedia Commons')}</a> · ${esc(p.license||'이용 조건은 원문 확인')}</p>`:'';}
function dayTabs(t){return `<div class="days" aria-label="여행 날짜">${allDates(t).map((d,i)=>`<button class="day-tab" data-action="select-day" data-date="${d}" aria-selected="${d===chosenDate}"><b>${i+1}일차</b><span>${d.slice(5).replace('-','/')}</span><small>${itemsOn(t,d).length}곳</small></button>`).join('')}</div>`;}
function renderPlan(t){const during=view==='during',items=itemsOn(t,chosenDate);$('#view').innerHTML=heading(during?'LIVE YOUR JOURNEY':'MAKE IT YOUR JOURNEY',during?'여행중':'여행 계획 세우기',during?'지금의 일정과 실제 시간을 기록하세요.':'지도에서 장소를 고르고, 나만의 순서로 담으세요.')+dayTabs(t)+`<div class="split"><div><span class="pill gold">${dayNumber(chosenDate,t)}일차</span><h2 style="font-size:20px;margin:10px 0">${koreanDate(chosenDate)}</h2></div><button class="btn compact" data-action="edit-trip">기간 변경</button></div><div class="actions" style="margin:4px 0 20px"><button class="btn primary" data-action="add-item">＋ 일정 추가</button><button class="btn" data-action="map">${icon('map')} 지도에서 선택</button>${during?'<button class="btn" data-action="record">사진·기록</button>':''}</div>${items.length?items.map((x,i)=>`<article class="plan-item"><div class="split"><span class="pill">${esc(x.kind)}${x.isFeatured?' · 대표':''}</span><span class="pill ${x.status}">${statusNames[x.status]}</span></div><h3><span class="order">${i+1}.</span> ${esc(x.title)}</h3><div class="plan-meta">${esc([x.startTime,x.endTime].filter(Boolean).join(' ~ ')||'시간 미정')}${x.area?' · '+esc(x.area):''}${x.address?'<br>'+esc(x.address):''}${x.actualStart||x.actualEnd?'<br>실제 '+esc([x.actualStart,x.actualEnd].filter(Boolean).join(' ~ ')):''}</div>${x.memo?`<p class="mini-text">${esc(x.memo)}</p>`:''}<div class="actions"><button class="btn compact" data-action="edit-item" data-id="${x.id}">수정</button>${during?`<button class="btn compact soft" data-action="arrive" data-id="${x.id}">도착</button><button class="btn compact primary" data-action="done" data-id="${x.id}">완료</button>`:`<button class="btn compact" data-action="move-up" data-id="${x.id}" ${i===0?'disabled':''}>↑</button><button class="btn compact" data-action="move-down" data-id="${x.id}" ${i===items.length-1?'disabled':''}>↓</button>`}<button class="btn compact" data-action="record" data-place="${x.id}">기록 남기기</button><button class="btn compact" data-action="directions" data-id="${x.id}">길찾기</button></div></article>`).join(''):`<div class="empty"><h2>이날의 첫 일정을 담아보세요.</h2><p>방문할 장소나 식당, 쉬어 가는 시간도<br>원하는 이름으로 직접 적을 수 있어요.</p></div>`}`+outsideItems(t);const tab=$('.day-tab[aria-selected=true]'),container=$('.days');if(tab)container.scrollLeft=Math.max(0,tab.offsetLeft-container.offsetLeft-15);}
function outsideItems(t){const arr=t.itinerary.filter(x=>!inTrip(x.date,t)).sort((a,b)=>a.date.localeCompare(b.date)||a.order-b.order);return arr.length?`<section class="card gap-top" id="outside-items"><h2>기간 밖 보관 일정</h2><p class="mini-text">여행 기간을 변경해도 삭제하지 않았습니다. 수정 버튼에서 새 날짜로 옮기거나, 여행 기간을 다시 늘릴 수 있습니다.</p>${arr.map(x=>`<div class="split" style="border-top:1px solid #e4ece4;padding:12px 0;gap:14px"><div><small>${esc(x.date)}</small><p style="margin:4px 0;overflow-wrap:anywhere">${esc(x.title)}</p></div><button class="btn compact" data-action="edit-item" data-id="${x.id}">날짜·내용 수정</button></div>`).join('')}</section>`:'';}
function renderAfter(t){const records=[...t.records].sort((a,b)=>a.date.localeCompare(b.date)||a.createdAt.localeCompare(b.createdAt));$('#view').innerHTML=heading('MOMENTS TO REMEMBER','여행후','사진과 느낀 점을 날짜별로 남기세요.')+`<div class="actions" style="margin-bottom:21px"><button class="btn primary" data-action="record">＋ 사진·기록 추가</button><button class="btn" data-go="report">보고서 보기</button></div>${records.length?records.map(r=>`<article class="card"><div class="split"><span class="pill">${koreanDate(r.date)}</span><button class="text-btn" data-action="edit-record" data-id="${r.id}">수정</button></div><h2 style="margin-top:14px">${esc(r.title)}</h2>${r.mood?`<span class="mini-text">${esc(r.mood)}</span>`:''}${r.placeId?`<div class="mini-text">${esc(t.itinerary.find(x=>x.id===r.placeId)?.title||'연결된 장소')}</div>`:''}<p class="record-body">${esc(r.body)}</p>${r.summary?`<div class="summary-box">${esc(r.summary)}</div>`:''}<div class="record-photos">${r.photoIds.map(id=>`<button style="padding:0;border:0;background:none" data-action="view-photo" data-id="${id}">${photoHTML(id)}</button>`).join('')}</div></article>`).join(''):`<div class="empty"><div class="empty-icon">${icon('photo')}</div><h2>기억하고 싶은 순간을 담으세요.</h2><p>사진, 장소와 느낀 점을 함께 저장하면<br>여행 보고서에도 자동으로 연결됩니다.</p></div>`}`;}
function renderReport(t){$('#view').innerHTML=heading('YOUR TRAVEL, ON PAPER','보고서','일정과 사진, 마음에 남은 이야기를 한 문서에 담아요.')+`<section class="card gap-top"><h2>보고서에 담을 내용</h2><label class="check-label"><input id="r-schedules" type="checkbox" checked>날짜별 일정</label><label class="check-label"><input id="r-photos" type="checkbox" checked>대표 사진·기록 사진</label><label class="check-label"><input id="r-packing" type="checkbox">준비물 체크리스트</label><p class="mini-text">제목·주제·기간·동행자와 감상 요약은 항상 포함합니다. 직접 쓴 요약이 없으면 본문 앞 세 문장을 발췌합니다.</p><div class="actions"><button class="btn primary full" data-action="preview">${icon('eye')} 보고서 미리보기</button><button class="btn full" data-action="print">${icon('report')} PDF 미리보기·저장 / 인쇄</button></div></section><div class="grid"><div class="card"><div class="count-stat">${t.itinerary.length}<small>개 일정</small></div></div><div class="card"><div class="count-stat">${t.records.length}<small>개 기록</small></div></div><p class="notice neutral gap-top">미리보기에서 내용을 확인한 뒤 PDF 저장을 누르세요. Android 인쇄 창에서 실제 페이지를 확인하고, 상단 대상을 ‘PDF로 저장’ 또는 프린터로 선택합니다.</p>`;}
function renderList(){const active=state.trips.filter(t=>!t.deletedAt).sort((a,b)=>b.startDate.localeCompare(a.startDate)),deleted=state.trips.filter(t=>t.deletedAt);$('#view').innerHTML=heading('ALL MY TRAVEL CHAPTERS','내가 그동안 다닌 여행목록','지난 여행도, 곧 떠날 여행도 한곳에서 만나보세요.')+`<div class="actions" style="margin-bottom:20px"><button class="btn primary" data-action="new">＋ 새 여행</button><button class="btn" data-go="settings">백업·복원</button></div>${active.length?active.map(t=>`<article class="card"><div class="trip-tile">${photo(t.coverId)?photoHTML(t.coverId,'thumb'): '<div class="thumb"></div>'}<div class="body"><h3>${esc(t.title)}</h3><p class="mini-text">${esc(t.startDate)} — ${esc(t.endDate)}<br>${t.itinerary.length}개 일정 · ${t.records.length}개 기록</p></div></div><div class="actions"><button class="btn primary compact" data-action="open-trip" data-id="${t.id}">여행 열기</button><button class="btn compact" data-action="trash-trip" data-id="${t.id}">휴지통으로</button></div></article>`).join(''):noTrip()}${deleted.length?`<details class="card"><summary>휴지통 · ${deleted.length}개 여행</summary>${deleted.map(t=>`<div class="split" style="padding-top:15px"><span class="mini-text">${esc(t.title)}</span><button class="btn compact" data-action="restore-trip" data-id="${t.id}">복원</button></div>`).join('')}</details>`:''}`;}
function renderSettings(){$('#view').innerHTML=heading('YOUR DATA, YOUR DEVICE','설정과 백업','중요한 여행과 사진은 백업 파일로 보관하세요.')+`<section class="card gap-top"><h2>여행·사진 전체 백업</h2><p class="subtitle">준비물, 일정, 기록과 사진을 JSON 한 파일에 담습니다. 앱 삭제·기기 변경 전에 꼭 백업하세요.</p><div class="actions"><button class="btn primary" data-action="backup">백업 파일 저장</button><button class="btn" data-action="restore">백업 불러오기</button></div><p class="mini-text">복원은 기존 여행을 덮어쓰지 않고 새 여행으로 추가합니다. 사진이 많은 여행은 백업에 시간이 걸릴 수 있습니다.</p></section><section class="card"><h2>기존 여행담 웹사이트</h2><p class="subtitle">기존 계정에 저장한 여행은 원래 웹사이트에서 확인합니다. 이번 앱의 기기 저장 기록과 자동 연결되지는 않습니다.</p><button class="btn gap-top" data-action="old-site">기존 여행담 열기 ↗</button></section><section class="card"><h2>내 사진과 개인정보</h2><p class="subtitle">이 앱은 로그인 없이 사용합니다. 여행과 직접 선택한 사진은 이 기기에 저장하며, 앱 서버로 올리지 않습니다. 지도·이미지 검색을 실행할 때만 검색어와 접속 정보가 해당 제공자에 전송됩니다.</p><p class="mini-text">지도: OpenStreetMap · 장소 검색: Photon · 이미지: Wikimedia Commons. 자동 AI 요약, 서버 동기화 및 공공데이터포털 인증 API는 이 설치판에 포함되지 않습니다. 공유하는 PDF에 사진의 이용 조건·출처를 유지하세요.</p></section><section class="card"><h2>여행담 1.0.0</h2><p class="subtitle">안드로이드 8.0 이상을 대상으로 만든 기기 저장형 설치판입니다. 저장한 앱 데이터는 재실행해도 유지됩니다. 앱 삭제 또는 앱 데이터 초기화 시 함께 삭제됩니다.</p><p class="mini-text">APK 개인 설치판 · 스토어 심사판 아님<br>백업에는 사진·동행자 정보가 포함될 수 있으니 개인적으로 보관하세요.</p></section>`;}
function modal(title,html,cls='',cleanup=null){closeModal(true);modalCleanup=cleanup;dirtyForm=false;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><h2>${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="닫기">×</button></header><div class="modal-body">${html}</div></section></div>`;document.body.classList.add('has-modal');}
function closeModal(force=false){if(!force&&dirtyForm&&!window.confirm('입력 중인 내용을 저장하지 않고 닫을까요?'))return false;modalCleanup?.();modalCleanup=null;mapCtl?.destroy();mapCtl=null;$('#modal-root').innerHTML='';document.body.classList.remove('has-modal');dirtyForm=false;return true;}
function val(name){return $(`[name="${name}"]`)?.value.trim()||'';}
function timeNow(){return new Date().toTimeString().slice(0,5);}
function formError(msg){const el=$('#form-error');if(el)el.textContent=msg;else notify(msg);}
function dateFields(start,end){return `<div class="grid"><label class="field">출발일<input type="date" name="startDate" value="${esc(start)}" min="1900-01-01" max="2199-12-31" required></label><label class="field">마지막 날<input type="date" name="endDate" value="${esc(end)}" min="1900-01-01" max="2199-12-31" required></label></div>`;}
function editTrip(isNew=false){const t=isNew?{title:'',theme:'',description:'',destination:'',people:'',startDate:todayISO(),endDate:''}:clone(trip());if(!t)return;modal(isNew?'새 여행 만들기':'여행 정보 편집',`<form id="edit-trip-form"><p class="notice neutral">여행 기간부터 정해 주세요. 당일 여행부터 120일까지 자유롭게 설정할 수 있습니다.</p>${dateFields(t.startDate,t.endDate)}<p id="period-label" class="mini-text"></p><label class="field">여행 제목<textarea name="title" rows="2" maxlength="120" placeholder="예: 우리 가족, 바다로 떠나는 시간" required>${esc(t.title)}</textarea></label><label class="field">여행 주제<input name="theme" value="${esc(t.theme)}" maxlength="150" placeholder="직접 적어주세요. 예: 느긋한 맛집 여행"></label><label class="field">여행 지역<input name="destination" value="${esc(t.destination)}" maxlength="150" placeholder="예: 강릉 · 속초"></label><label class="field">동행자 이름<input name="people" value="${esc(t.people)}" maxlength="500" placeholder="함께하는 사람을 간단히 적어주세요"></label><label class="field">여행 소개·자유 메모<textarea name="description" rows="4" maxlength="10000">${esc(t.description)}</textarea></label><p class="mini-text">기간 밖으로 나가는 기존 일정·사진은 삭제하지 않고 보관합니다. 저장 전 안내를 표시합니다.</p><div id="form-error" class="form-error" role="alert"></div><div class="form-actions"><button class="btn" type="button" data-action="close">취소</button><button class="btn primary" type="submit">여행 저장</button></div></form>`);const f=$('#edit-trip-form');f.addEventListener('input',()=>{const a=val('startDate'),b=val('endDate'),n=tripDays({startDate:a,endDate:b});$('#period-label').textContent=n?`${n===1?'당일 여행':`${n-1}박 ${n}일`} · ${a} — ${b}`:'출발일과 마지막 날을 선택하세요.';dirtyForm=true;});f.addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(form.dataset.saving==='1')return;form.dataset.saving='1';const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{const next={title:val('title'),theme:val('theme'),description:val('description'),destination:val('destination'),people:val('people'),startDate:val('startDate'),endDate:val('endDate')};if(!next.title)throw new Error('여행 제목을 적어 주세요.');if(!validRange(next)||tripDays(next)>120)throw new Error('출발일 이후의 마지막 날을 선택하세요. 여행 기간은 최대 120일입니다.');if(!isNew){const outside=t.itinerary.filter(x=>!inTrip(x.date,next)).length+t.records.filter(x=>!inTrip(x.date,next)).length;if(outside&&!window.confirm(`새 기간 밖에 일정·기록 ${outside}개가 있습니다. 삭제하지 않고 보관합니다. 기간을 변경할까요?`))return;}let id=isNew?uid():t.id;await commit(s=>{if(isNew){s.trips.push({id,...next,coverId:null,packing:[],itinerary:[],records:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),deletedAt:null});}else{Object.assign(s.trips.find(x=>x.id===id),next,{updatedAt:new Date().toISOString()});}s.currentId=id;});closeModal(true);chosenDate=next.startDate;view='main';render();notify('여행을 저장했습니다.');}catch(err){formError(errorMessage(err));}finally{form.dataset.saving='';if(submit?.isConnected)submit.disabled=false;}});}
function editItem(id=null,prefill={}){const t=trip();if(!t)return;const x=id?clone(t.itinerary.find(a=>a.id===id)):{date:chosenDate,title:'',kind:'볼거리',area:'',address:'',startTime:'',endTime:'',actualStart:'',actualEnd:'',status:'planned',memo:'',isFeatured:false,lat:null,lng:null,...prefill};if(!x)return;modal(id?'일정 수정':'여행 일정 추가',`<form id="item-form"><label class="field">방문 날짜<input name="date" type="date" value="${esc(x.date)}" min="${t.startDate}" max="${t.endDate}" required></label><label class="field">일정 제목·장소 이름<input name="title" maxlength="150" value="${esc(x.title)}" placeholder="예: 경포해변 산책, 점심 먹기" required></label><div class="grid"><label class="field">분류<input name="kind" maxlength="50" value="${esc(x.kind)}" list="kind-options"><datalist id="kind-options"><option>볼거리</option><option>식당</option><option>카페</option><option>숙소</option><option>지역 이동</option><option>쉬어 가기</option></datalist></label><label class="field">지역 이름<input name="area" maxlength="120" value="${esc(x.area)}" placeholder="예: 강릉"></label></div><div class="grid"><label class="field">예정 시작<input name="startTime" type="time" value="${esc(x.startTime)}"></label><label class="field">예정 종료<input name="endTime" type="time" value="${esc(x.endTime)}"></label></div><div class="grid"><label class="field">실제 도착<input name="actualStart" type="time" value="${esc(x.actualStart)}"></label><label class="field">실제 완료<input name="actualEnd" type="time" value="${esc(x.actualEnd)}"></label></div><label class="field">진행 상태<select name="status">${Object.entries(statusNames).map(([v,l])=>`<option value="${v}" ${x.status===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="check-label"><input type="checkbox" name="featured" ${x.isFeatured?'checked':''}>이날의 대표 일정으로 표시</label><p class="mini-text">대표로 선택한 일정이 있으면 달력 아래에는 대표 일정 제목만 표시합니다. 없으면 해당 날짜의 일정 제목을 순서대로 표시합니다.</p><label class="field">주소<input name="address" maxlength="500" value="${esc(x.address)}"></label><label class="field">메뉴·예약·예산·자유 메모<textarea name="memo" rows="4" maxlength="10000">${esc(x.memo)}</textarea></label>${Number.isFinite(x.lat)?`<p class="mini-text">지도 위치 저장됨 · ${x.lat.toFixed(5)}, ${x.lng.toFixed(5)}</p>`:''}<div id="form-error" class="form-error"></div><div class="form-actions">${id?`<button class="btn danger" type="button" data-action="delete-item" data-id="${id}">삭제</button>`:'<button class="btn" type="button" data-action="close">취소</button>'}<button class="btn primary" type="submit">일정 저장</button></div></form>`);$('#item-form').addEventListener('input',()=>{dirtyForm=true;});$('#item-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(form.dataset.saving==='1')return;form.dataset.saving='1';const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{const next={...x,title:val('title'),date:val('date'),kind:val('kind')||'일정',area:val('area'),address:val('address'),memo:val('memo'),startTime:val('startTime'),endTime:val('endTime'),actualStart:val('actualStart'),actualEnd:val('actualEnd'),status:val('status'),isFeatured:$('[name=featured]').checked};if(!next.title||!inTrip(next.date,t))throw new Error('일정 제목과 여행 기간 안의 날짜를 입력하세요.');if(next.startTime&&next.endTime&&next.endTime<next.startTime)throw new Error('종료 시간을 시작 이후로 정해 주세요. 자정을 넘는 일정은 날짜별로 나누어 주세요.');await commit(s=>{const live=s.trips.find(a=>a.id===t.id);if(id){const i=live.itinerary.findIndex(a=>a.id===id);if(i<0)throw new Error('수정할 일정을 찾지 못했습니다.');if(next.date!==x.date)next.order=live.itinerary.filter(a=>a.date===next.date).length;live.itinerary[i]=next;}else{next.id=uid();next.order=live.itinerary.filter(a=>a.date===next.date).length;live.itinerary.push(next);}live.updatedAt=new Date().toISOString();});chosenDate=next.date;closeModal(true);render();notify('일정을 저장했습니다. 달력에도 반영됩니다.');}catch(err){formError(errorMessage(err));}finally{form.dataset.saving='';if(submit?.isConnected)submit.disabled=false;}});}
async function storePhoto(file,metadata={}){if(!(file instanceof Blob))throw new Error('사진 파일을 읽을 수 없습니다.');if(file.size>20*1024*1024)throw new Error('사진은 한 장당 20MB 이하로 선택해 주세요.');if(file.type&&!/^image\/(jpeg|png|webp|gif|bmp)$/.test(file.type))throw new Error('JPEG·PNG·WebP 사진을 선택해 주세요.');const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('사진을 읽지 못했습니다. JPEG 또는 PNG로 변환해 주세요.'));});if(image.width*image.height>90000000)throw new Error('사진 해상도가 너무 큽니다. 크기를 줄인 사진을 선택해 주세요.');const scale=Math.min(1,1440/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.82);if(data.length>2500000)throw new Error('압축한 사진이 너무 큽니다. 더 작은 사진을 선택해 주세요.');const p={id:uid(),data,mime:'image/jpeg',author:String(metadata.author||''),license:String(metadata.license||''),sourceURL:safeURL(metadata.sourceURL||''),createdAt:new Date().toISOString()};await new Promise((resolve,reject)=>{const tx=db.transaction('photos','readwrite');tx.objectStore('photos').put(p);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});photoMap.set(p.id,p);return p;}finally{URL.revokeObjectURL(url);}}
function coverDialog(){const t=trip();if(!t)return;modal('대표 사진 넣기',`<p class="subtitle">휴대폰의 사진을 선택하면 여행 표지로 저장됩니다.</p><label class="field gap-top">사진 선택<input id="cover-file" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="mini-text">최대 1440px로 줄여 기기에 저장합니다. 원본 사진 파일은 바꾸지 않습니다.</p><div id="cover-status" class="form-error"></div>${t.coverId?'<button class="btn danger" data-action="remove-cover">대표 사진 빼기</button>':''}`);$('#cover-file').addEventListener('change',async e=>{let file=e.target.files[0];if(!file)return;$('#cover-status').textContent='사진을 저장하고 있습니다…';try{let p=await storePhoto(file);await commit(s=>{s.trips.find(x=>x.id===t.id).coverId=p.id;});closeModal(true);render();notify('대표 사진을 등록했습니다.');}catch(err){$('#cover-status')&&($('#cover-status').textContent=errorMessage(err));}});}
function excerpt(text){return String(text||'').trim().split(/(?<=[.!?。！？])\s+|\n+/).filter(Boolean).slice(0,3).join(' ').slice(0,600);}
function recordEditor(id=null,date=chosenDate,placeId=''){const t=trip();if(!t)return;const r=id?clone(t.records.find(x=>x.id===id)):{date:inTrip(date,t)?date:t.startDate,title:'',placeId,body:'',summary:'',mood:'',photoIds:[]};if(!r)return;recordDraftPhotos=[...r.photoIds];modal(id?'여행 기록 수정':'사진과 여행 기록',`<form id="record-form"><div class="grid"><label class="field">기록 날짜<input name="date" type="date" value="${r.date}" min="${t.startDate}" max="${t.endDate}" required></label><label class="field">기분·느낌<input name="mood" maxlength="120" value="${esc(r.mood)}" placeholder="직접 입력"></label></div><label class="field">기록 제목<input name="title" value="${esc(r.title)}" maxlength="150" placeholder="예: 바다가 가장 예뻤던 순간" required></label><label class="field">연결할 장소<select name="placeId"><option value="">장소 연결 없이 기록</option>${t.itinerary.map(x=>`<option value="${x.id}" ${r.placeId===x.id?'selected':''}>${x.date.slice(5)} · ${esc(x.title)}</option>`).join('')}</select></label><label class="field">보고 느낀 점<textarea name="body" rows="5" maxlength="20000" placeholder="볼거리, 먹거리, 기억에 남는 이야기를 적어주세요.">${esc(r.body)}</textarea></label><label class="field">보고서에 담을 요약<textarea name="summary" rows="3" maxlength="3000" placeholder="직접 요약하거나 아래 발췌 버튼을 사용하세요.">${esc(r.summary)}</textarea></label><button type="button" class="text-btn" id="extract-summary">본문 앞부분을 요약 초안으로 가져오기</button><p class="mini-text">AI 생성이 아닌 본문 앞 세 문장 발췌입니다. 자유롭게 수정할 수 있습니다.</p><label class="field gap-top">사진 추가<input type="file" id="record-files" accept="image/jpeg,image/png,image/webp" multiple><small>기록별 최대 12장. 휴대폰에서는 사진을 한 장씩 추가할 수도 있습니다.</small></label><div id="draft-photos" class="photo-grid"></div><div id="photo-status" class="mini-text"></div><div id="form-error" class="form-error"></div><div class="form-actions">${id?`<button type="button" class="btn danger" data-action="delete-record" data-id="${id}">삭제</button>`:'<button type="button" class="btn" data-action="close">취소</button>'}<button type="submit" class="btn primary" id="record-save">기록 저장</button></div></form>`);renderDraftPhotos();$('#extract-summary').onclick=()=>{$('[name=summary]').value=excerpt(val('body'));dirtyForm=true;};$('#record-form').addEventListener('input',()=>{dirtyForm=true;});$('#record-files').addEventListener('change',async e=>{const input=e.target,files=Array.from(input.files||[]);if(files.length+recordDraftPhotos.length>12){formError('한 기록에 사진은 최대 12장까지 담을 수 있습니다.');return;}let btn=$('#record-save');btn.disabled=true;try{for(const file of files){$('#photo-status').textContent='사진을 준비하고 있습니다…';const p=await storePhoto(file);recordDraftPhotos.push(p.id);}renderDraftPhotos();dirtyForm=true;$('#photo-status').textContent='사진을 준비했습니다. 아래 기록 저장을 눌러주세요.';}catch(err){formError(errorMessage(err));}finally{if(btn.isConnected)btn.disabled=false;input.value='';}});$('#record-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(form.dataset.saving==='1')return;form.dataset.saving='1';const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{const next={...r,title:val('title'),date:val('date'),placeId:val('placeId'),body:val('body'),summary:val('summary'),mood:val('mood'),photoIds:[...recordDraftPhotos]};if(!next.title||!inTrip(next.date,t))throw new Error('제목과 여행 기간 안의 날짜를 입력하세요.');await commit(s=>{const live=s.trips.find(x=>x.id===t.id);if(id){const i=live.records.findIndex(x=>x.id===id);if(i<0)throw new Error('기록을 찾을 수 없습니다.');live.records[i]=next;}else{next.id=uid();next.createdAt=new Date().toISOString();live.records.push(next);}live.updatedAt=new Date().toISOString();});closeModal(true);render();notify('여행 기록과 사진을 저장했습니다.');}catch(err){formError(errorMessage(err));}finally{form.dataset.saving='';if(submit?.isConnected)submit.disabled=false;}});}
function renderDraftPhotos(){const el=$('#draft-photos');if(el)el.innerHTML=recordDraftPhotos.map(id=>`<div class="photo-cell">${photoHTML(id)}<button type="button" data-action="remove-draft-photo" data-id="${id}" aria-label="사진 제외">×</button></div>`).join('');}
function reportOptions(){return {schedules:$('#r-schedules')?.checked??true,photos:$('#r-photos')?.checked??true,packing:$('#r-packing')?.checked??false};}
function reportMarkup(t,options){const records=[...t.records].sort((a,b)=>a.date.localeCompare(b.date)||a.createdAt.localeCompare(b.createdAt));const dates=[...new Set([...allDates(t),...t.itinerary.map(x=>x.date)])].sort();return `<article class="paper"><section class="r-cover"><p class="eyebrow">YEOHAENGDAM · MY TRAVEL CHAPTER</p><h1>${esc(t.title)}</h1>${t.theme?`<p style="font-weight:700;color:#668574">${esc(t.theme)}</p>`:''}<div class="r-meta"><span>${esc(t.startDate)} — ${esc(t.endDate)} · ${tripDays(t)}일</span><span>${esc(t.destination)}</span><span>${esc(t.people)}</span></div>${options.photos&&photo(t.coverId)?photoHTML(t.coverId,'cover-print',t.title)+attribution(photo(t.coverId)):''}<p class="r-body">${esc(t.description)}</p></section>${options.schedules?`<h2>날짜별 여행 일정</h2>${dates.map(d=>`<section><h3>${koreanDate(d,true)}${!inTrip(d,t)?' · 기간 밖 보관 일정':''}</h3>${itemsOn(t,d).length?itemsOn(t,d).map((x,i)=>`<div class="r-step"><strong>${i+1}. ${esc(x.title)}</strong><small>${esc([x.startTime,x.endTime].filter(Boolean).join(' ~ ')||'시간 미정')} · ${esc(x.kind)} · ${statusNames[x.status]}${x.isFeatured?' · 대표 일정':''}</small>${x.actualStart||x.actualEnd?`<small>실제 ${esc([x.actualStart,x.actualEnd].filter(Boolean).join(' ~ '))}</small>`:''}<small>${esc([x.area,x.address].filter(Boolean).join(' · '))}</small>${x.memo?`<p>${esc(x.memo)}</p>`:''}</div>`).join(''):'<p>등록된 일정이 없습니다.</p>'}</section>`).join('')}`:''}<h2>기억에 남은 순간</h2>${records.length?records.map(r=>`<section class="r-record"><h3>${esc(r.title)}</h3><p class="mini-text">${koreanDate(r.date,true)}${r.mood?' · '+esc(r.mood):''}${r.placeId?' · '+esc(t.itinerary.find(x=>x.id===r.placeId)?.title||''):''}</p>${r.summary||r.body?`<p class="r-summary">${esc(r.summary||excerpt(r.body))}</p><p style="font-size:9px;color:#83917e">${r.summary?'직접 작성한 요약':'본문 앞부분 발췌 · AI 생성 아님'}</p>`:'<p>아직 감상을 작성하지 않았습니다.</p>'}${options.photos&&r.photoIds.length?`<div class="r-photos">${r.photoIds.map((id,i)=>photo(id)?`<figure>${photoHTML(id)}<figcaption>${esc(r.title)} · ${i+1}${photo(id)?.sourceURL?`<br>${esc(photo(id).author)} · ${esc(photo(id).license)}`:''}</figcaption></figure>`:'').join('')}</div>`:''}</section>`).join(''):'<p>여행 사진과 감상 기록을 추가하면 이곳에 담깁니다.</p>'}${options.packing?`<h2>준비물 챙기기</h2><p>${t.packing.filter(x=>x.checked).length} / ${t.packing.length}개 준비 완료</p><ul>${t.packing.map(x=>`<li>${x.checked?'☑':'☐'} ${esc(x.text)}</li>`).join('')}</ul>`:''}<footer class="r-foot">여행담 · 기기 저장형 보고서 · ${esc(new Date().toLocaleString('ko-KR'))}<br>작성한 기록을 바탕으로 정리했습니다. 검색 사진의 출처와 이용 조건은 유지해 주세요.</footer></article>`;}
let currentReport='',currentReportTitle='여행담 보고서';
async function previewReport(printAfter=false){const t=trip();if(!t)return;await commitTail.catch(()=>{});currentReport=reportMarkup(t,reportOptions());currentReportTitle=t.title;modal('여행 보고서 미리보기',currentReport,'report');$('.report .modal-head').insertAdjacentHTML('afterend',`<div class="report-toolbar"><button class="btn primary" data-action="print-current">PDF 저장 / 인쇄</button><span>내용 미리보기 · 최종 페이지는 인쇄 창에서 확인</span></div>`);if(printAfter)setTimeout(printCurrent,100);}
const PRINT_CSS=`body{margin:0;background:white;font-family:sans-serif;color:#24483d}.paper{font-family:sans-serif;line-height:1.65;padding:18px;font-size:12px;overflow-wrap:anywhere}.paper h1{font-size:30px;white-space:pre-line;line-height:1.3;margin:16px 0}.paper h2{font-size:20px;margin:30px 0 16px;border-bottom:1px solid #bdcfbf;padding-bottom:8px;break-after:avoid}.paper h3{font-size:15px;margin:22px 0 8px;break-after:avoid}.paper p{font-size:12px;line-height:1.85;orphans:3;widows:3}.paper .eyebrow{font-size:10px;color:#648374;letter-spacing:2px}.paper .r-meta{font-size:11px;color:#718775;line-height:1.9}.paper .r-meta span{margin-right:14px}.paper .cover-print{width:100%;max-height:300px;object-fit:cover}.paper .attribution{font-size:9px;color:#7d917e}.paper .r-body{white-space:pre-line}.paper .r-step{padding:12px 0;border-bottom:1px solid #e0e7df;break-inside:avoid}.paper .r-step strong{font-size:13px}.paper .r-step small{display:block;font-size:10px;line-height:1.7;color:#728474}.paper .r-summary{background:#eff5ef;padding:14px;white-space:pre-line}.paper .r-photos{display:flex;flex-wrap:wrap;gap:12px}.paper figure{width:calc(50% - 10px);margin:5px 0;break-inside:avoid}.paper figure img{width:100%;height:180px;object-fit:cover}.paper figcaption{font-size:9px;color:#81927e}.paper .r-foot{border-top:1px solid #dce5da;margin-top:35px;padding-top:15px;font-size:9px;color:#82947c}a{color:#557963}@page{size:A4;margin:16mm}`;
function printDocument(){return `<!doctype html><html lang="ko"><head><meta charset="utf-8"><title>${esc(currentReportTitle)}</title><style>${PRINT_CSS}</style></head><body>${currentReport.replaceAll(' loading="lazy"','')}</body></html>`;}
function printCurrent(){if(!currentReport)return;const html=printDocument();if(html.length>60000000){notify('사진이 너무 많습니다. 보고서에서 사진 포함을 해제해 주세요.');return;}if(isNative){native('YD_PRINT',html);return;}const win=window.open('','_blank');if(!win){notify('미리보기 팝업이 차단되었습니다. 브라우저의 팝업 설정을 확인하세요.');return;}win.document.open();win.document.write(html);win.document.close();setTimeout(()=>win.print(),600);}
async function backup(){await commitTail.catch(()=>{});const refs=new Set();for(const t of state.trips){if(t.coverId)refs.add(t.coverId);for(const r of t.records)for(const id of r.photoIds)refs.add(id);}const payload={app:'yeohaengdam-device',schema:1,exportedAt:new Date().toISOString(),state,photos:[...refs].map(id=>photo(id)).filter(Boolean)};const text=JSON.stringify(payload);if(text.length>60000000){notify('백업 크기가 60MB를 초과합니다. 기록 사진을 줄인 뒤 다시 시도해 주세요.');return;}if(isNative){native('YD_SAVE',text);notify('저장할 위치를 선택하세요.');return;}const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`여행담_전체백업_${todayISO()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('백업 파일을 만들었습니다.');}
function cleanBackup(raw){if(!raw||raw.app!=='yeohaengdam-device'||raw.schema!==1||!Array.isArray(raw.state?.trips)||!Array.isArray(raw.photos))throw new Error('여행담 설치판에서 저장한 백업 파일을 선택해 주세요.');if(raw.state.trips.length>200||raw.photos.length>1000)throw new Error('백업에 들어 있는 항목 수가 너무 많습니다.');const text=(v,max=10000)=>{if(v==null)return '';if(typeof v!=='string'||v.length>max)throw new Error('백업의 문자열 형식이 올바르지 않습니다.');return v;};const idMap=new Map(),ids=new Set();const photos=raw.photos.map(p=>{if(!p||typeof p.id!=='string'||ids.has(p.id)||typeof p.data!=='string'||p.data.length>2500000||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p.data))throw new Error('백업의 사진 형식이 올바르지 않습니다.');ids.add(p.id);const id=uid();idMap.set(p.id,id);return{id,data:p.data,mime:'image/jpeg',author:text(p.author,500),license:text(p.license,300),sourceURL:safeURL(p.sourceURL),createdAt:new Date().toISOString()};});const getPhoto=id=>{if(!id)return null;if(!idMap.has(id))throw new Error('사진이 누락된 백업입니다. 원본 백업을 다시 선택하세요.');return idMap.get(id);};const trips=raw.state.trips.map(t=>{if(!validRange(t)||tripDays(t)>120||!Array.isArray(t.itinerary)||!Array.isArray(t.records)||t.itinerary.length>3000||t.records.length>1000)throw new Error('백업의 여행 기간 또는 일정 형식이 올바르지 않습니다.');const title=text(t.title,120);if(!title.trim())throw new Error('여행 제목이 없는 백업입니다.');const itIds=new Map();const itinerary=t.itinerary.map(x=>{if(!x||typeof x.id!=='string'||!x.id||itIds.has(x.id)||!parseDate(x.date)||!text(x.title,150).trim()||!Number.isInteger(x.order)||x.order<0||!statusNames[x.status])throw new Error('백업의 일정 데이터를 확인하세요.');const time=k=>{const v=text(x[k],5);if(v&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(v))throw new Error('잘못된 일정 시간입니다.');return v;};const id=uid();itIds.set(x.id,id);return{id,date:x.date,title:x.title,kind:text(x.kind,50),area:text(x.area,120),address:text(x.address,500),memo:text(x.memo),startTime:time('startTime'),endTime:time('endTime'),actualStart:time('actualStart'),actualEnd:time('actualEnd'),status:x.status,isFeatured:x.isFeatured===true,order:x.order,lat:Number.isFinite(x.lat)&&Math.abs(x.lat)<=85?x.lat:null,lng:Number.isFinite(x.lng)&&Math.abs(x.lng)<=180?x.lng:null};});const records=t.records.map(r=>{if(!r||!parseDate(r.date)||!text(r.title,150).trim()||!Array.isArray(r.photoIds)||r.photoIds.length>12)throw new Error('백업의 기록 데이터를 확인하세요.');return{id:uid(),date:r.date,title:r.title,placeId:itIds.get(r.placeId)||'',body:text(r.body,20000),summary:text(r.summary,3000),mood:text(r.mood,120),photoIds:r.photoIds.map(getPhoto),createdAt:text(r.createdAt,100)};});return{id:uid(),title,theme:text(t.theme,150),description:text(t.description),destination:text(t.destination,150),people:text(t.people,500),startDate:t.startDate,endDate:t.endDate,coverId:getPhoto(t.coverId),packing:validatePacking(t.packing||[]).map(x=>({...x,id:uid()})),itinerary,records,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),deletedAt:t.deletedAt?new Date().toISOString():null};});return{trips,photos};}
async function restoreFile(file){if(!file)return;if(file.size>60000000){notify('백업 파일은 60MB 이하로 선택하세요.');return;}try{const raw=JSON.parse(await file.text()),clean=cleanBackup(raw);modal('백업 확인',`<p class="subtitle">${clean.trips.length}개 여행, ${clean.photos.length}장 사진을 확인했습니다.</p><p class="notice neutral gap-top">기존 기록은 그대로 두고 새 여행으로 추가합니다. 같은 백업을 여러 번 불러오면 중복 여행이 생깁니다.</p><div class="form-actions"><button class="btn" data-action="close">취소</button><button class="btn primary" id="confirm-restore">복원하기</button></div>`);$('#confirm-restore').onclick=async()=>{const b=$('#confirm-restore');b.disabled=true;try{await commitTail.catch(()=>{});const next=clone(state);next.trips.push(...clean.trips);if(clean.trips.find(t=>!t.deletedAt))next.currentId=clean.trips.find(t=>!t.deletedAt).id;await dbWrite(next,clean.photos);state=next;for(const p of clean.photos)photoMap.set(p.id,p);closeModal(true);navigate('list');notify('백업을 복원했습니다.');}catch(err){b.disabled=false;notify(errorMessage(err));}};}catch(err){notify(errorMessage(err));}}
async function fetchJSON(url,timeout=18000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const r=await fetch(url,{signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw new Error(`검색 서비스 응답 오류 (${r.status})`);return await r.json();}catch(e){if(e.name==='AbortError')throw new Error('검색 응답이 늦습니다. 인터넷 연결을 확인하고 다시 검색하세요.');throw e;}finally{clearTimeout(timer);}}
function stripMarkup(text){const d=new DOMParser().parseFromString(String(text||''),'text/html');return d.body.textContent?.trim()||'';}
function imageSearch(){const t=trip();if(!t)return;const query=t.destination||t.title;modal('여행지 사진 찾기',`<p class="subtitle">여행지 이름으로 검색하고 사진을 고르면 대표 사진으로 저장됩니다.</p><form id="image-form" class="search-row"><input id="image-keyword" value="${esc(query)}" placeholder="예: 강릉, 제주, Kyoto" maxlength="100" aria-label="사진 검색어"><button class="btn primary">검색</button></form><p class="mini-text">검색어가 Wikimedia Commons로 전송됩니다. 직접 촬영한 여행 사진이 아니므로 출처를 함께 저장합니다.</p><div id="image-message" class="mini-text"></div><div id="image-results" class="grid gap-top"></div>`);let generation=0;async function search(){const keyword=$('#image-keyword')?.value.trim();if(!keyword)return;const gen=++generation;$('#image-message').textContent='사진을 찾는 중…';$('#image-results').innerHTML='';try{const params=new URLSearchParams({action:'query',generator:'search',gsrsearch:keyword+' filetype:bitmap',gsrnamespace:'6',gsrlimit:'12',prop:'imageinfo',iiprop:'url|extmetadata|mime',iiurlwidth:'1000',format:'json',origin:'*'});const data=await fetchJSON('https://commons.wikimedia.org/w/api.php?'+params);if(gen!==generation||!$('#image-results'))return;const rows=Object.values(data.query?.pages||{}).map(p=>{const im=p.imageinfo?.[0],url=im?.thumburl||im?.url;if(!im||!/^image\/(jpeg|png|webp)$/.test(im.mime)||!url)return null;let u;try{u=new URL(url);}catch{return null;}if(u.protocol!=='https:'||u.hostname!=='upload.wikimedia.org')return null;return{url:u.href,title:p.title.replace(/^File:/,''),author:stripMarkup(im.extmetadata?.Artist?.value).slice(0,500),license:stripMarkup(im.extmetadata?.LicenseShortName?.value).slice(0,300),sourceURL:im.descriptionurl};}).filter(Boolean);$('#image-message').textContent=rows.length?`${rows.length}장의 사진을 찾았습니다. 여행지와 일치하는지 확인 후 선택하세요.`:'사진이 없습니다. 지역명을 짧게 쓰거나 영어로 검색해 보세요.';$('#image-results').innerHTML=rows.map((p,i)=>`<article class="image-result"><img src="${esc(p.url)}" alt="${esc(p.title)}" loading="lazy"><div class="info"><p>${esc(p.title.slice(0,90))}</p><p class="mini-text">${esc(p.license||'원문 이용 조건 확인')}</p><a class="mini-text" href="${esc(safeURL(p.sourceURL))}">사진 출처 확인</a><button class="btn soft" type="button" data-photo-index="${i}">이 사진으로 등록</button></div></article>`).join('');$('#image-results').onclick=async e=>{const b=e.target.closest('[data-photo-index]');if(!b)return;b.disabled=true;const p=rows[Number(b.dataset.photoIndex)];try{b.textContent='사진 저장 중…';const r=await fetch(p.url,{credentials:'omit'});if(!r.ok)throw new Error('사진을 가져오지 못했습니다. 다른 사진을 선택해 주세요.');const item=await storePhoto(await r.blob(),p);await commit(s=>{s.trips.find(a=>a.id===t.id).coverId=item.id;});closeModal(true);render();notify('검색 사진을 대표 사진으로 등록했습니다.');}catch(err){notify(errorMessage(err));if(b.isConnected){b.disabled=false;b.textContent='이 사진으로 등록';}}};}catch(err){if($('#image-message'))$('#image-message').textContent='검색에 연결하지 못했습니다. 사진을 직접 선택해서 넣을 수 있습니다. '+errorMessage(err);}}$('#image-form').onsubmit=e=>{e.preventDefault();search();};if(query)search();}
// Small Web Mercator tile viewer: only visible tiles requested. No prefetch/offline tile download.
function createTileMap(element,initial,onPick){let center={lat:initial.lat,lng:initial.lng},zoom=13,markers=[],points=[],drag=null,moved=false,disposed=false;const project=(lat,lng,z)=>{const n=256*Math.pow(2,z),s=Math.sin(Math.max(-85,Math.min(85,lat))*Math.PI/180);return{x:(lng+180)/360*n,y:(.5-Math.log((1+s)/(1-s))/(4*Math.PI))*n};};const unproject=(x,y,z)=>{const n=256*2**z;return{lng:(x/n*360-180+540)%360-180,lat:Math.atan(Math.sinh(Math.PI*(1-2*y/n)))*180/Math.PI};};element.innerHTML=`<div class="map-tiles"></div><svg class="route-lines" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none"></svg><div class="map-pins"></div><div class="map-note">핀을 누르거나 빈 곳을 눌러 위치 선택</div><div class="map-buttons"><button type="button" aria-label="지도 확대">＋</button><button type="button" aria-label="지도 축소">−</button></div><div class="map-attribution">© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors</div>`;const tiles=element.querySelector('.map-tiles'),pins=element.querySelector('.map-pins'),svg=element.querySelector('svg');let raf;
 function draw(){if(disposed)return;const w=element.clientWidth,h=element.clientHeight,cp=project(center.lat,center.lng,zoom),left=cp.x-w/2,top=cp.y-h/2,N=2**zoom;let html='';for(let x=Math.floor(left/256);x<=Math.floor((left+w)/256);x++)for(let y=Math.floor(top/256);y<=Math.floor((top+h)/256);y++){if(y<0||y>=N)continue;html+=`<img alt="" draggable="false" src="https://tile.openstreetmap.org/${zoom}/${(x%N+N)%N}/${y}.png" style="left:${x*256-left}px;top:${y*256-top}px">`;}tiles.innerHTML=html;pins.innerHTML=markers.map((m,i)=>{const p=project(m.lat,m.lng,zoom);return `<button type="button" class="map-marker ${m.search?'search':''}" data-marker="${i}" style="left:${p.x-left}px;top:${p.y-top}px" aria-label="${esc(m.title)}"><span>${m.number||i+1}</span></button>`;}).join('');const line=points.map(m=>{const p=project(m.lat,m.lng,zoom);return `${p.x-left},${p.y-top}`;}).join(' ');svg.innerHTML=`<polyline points="${line}" fill="none" stroke="#176958" stroke-width="3" stroke-dasharray="6 5" opacity=".65"/>`;}
 function schedule(){cancelAnimationFrame(raf);raf=requestAnimationFrame(draw);}element.querySelectorAll('.map-buttons button').forEach((b,i)=>b.onclick=()=>{zoom=Math.max(4,Math.min(18,zoom+(i===0?1:-1)));schedule();});pins.onclick=e=>{const b=e.target.closest('[data-marker]');if(b)onPick(markers[Number(b.dataset.marker)]);};
 const down=e=>{if(e.target.closest('button,a'))return;drag={x:e.clientX,y:e.clientY,center:project(center.lat,center.lng,zoom)};moved=false;element.setPointerCapture(e.pointerId);};const move=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>6)moved=true;const c=unproject(drag.center.x-dx,drag.center.y-dy,zoom);center={lat:Math.max(-85,Math.min(85,c.lat)),lng:c.lng};schedule();};const up=e=>{if(!drag)return;if(!moved){const rect=element.getBoundingClientRect(),cp=project(center.lat,center.lng,zoom),c=unproject(cp.x+e.clientX-rect.left-element.clientWidth/2,cp.y+e.clientY-rect.top-element.clientHeight/2,zoom);onPick({...c,title:'선택한 위치',address:'',area:''});}drag=null;};element.addEventListener('pointerdown',down);element.addEventListener('pointermove',move);element.addEventListener('pointerup',up);element.addEventListener('pointercancel',()=>{drag=null;});const resize=new ResizeObserver(schedule);resize.observe(element);draw();return{setData(next,route){markers=next;points=route||[];schedule();},go(lat,lng,z){center={lat,lng};if(z)zoom=z;schedule();},destroy(){disposed=true;resize.disconnect();cancelAnimationFrame(raf);element.removeEventListener('pointerdown',down);element.removeEventListener('pointermove',move);element.removeEventListener('pointerup',up);}};}
function mapEditor(){const t=trip();if(!t)return;const saved=itemsOn(t,chosenDate).filter(x=>Number.isFinite(x.lat)&&Number.isFinite(x.lng)).map((x,i)=>({...x,number:i+1}));const initial=saved[0]||{lat:37.5665,lng:126.978};modal('지도에서 코스 짜기',`<p class="subtitle">${koreanDate(chosenDate)} · 장소 하나씩 내 일정에 담기</p><form id="place-form" class="search-row"><input id="place-keyword" placeholder="예: 강릉 식당, 성산일출봉" maxlength="150" aria-label="장소 검색어" value="${esc(t.destination)}"><button class="btn primary">검색</button></form><div id="travel-map" class="map"></div><p class="mini-text">지도·검색은 인터넷이 필요합니다. 점선은 방문 순서이며 도로 경로·소요시간이 아닙니다. 이름 검색은 OpenStreetMap 데이터라 누락된 식당이 있을 수 있습니다.</p><div id="selected-place"></div><p id="place-message" class="mini-text"></p><div id="place-results"></div>`);let searchResults=[];const choose=p=>{const box=$('#selected-place');if(!box)return;box.innerHTML=`<section class="card"><h3>${esc(p.title)}</h3><p class="mini-text">${esc(p.address||'이름을 직접 입력할 수 있습니다.')}<br>${p.lat.toFixed(5)}, ${p.lng.toFixed(5)}</p><button type="button" class="btn primary full" id="add-selected">이 장소를 일정에 추가</button></section>`;$('#add-selected').onclick=()=>editItem(null,{title:p.title==='선택한 위치'?'':p.title,address:p.address||'',area:p.area||'',lat:p.lat,lng:p.lng,date:chosenDate,kind:p.kind||'볼거리'});};mapCtl=createTileMap($('#travel-map'),initial,choose);mapCtl.setData(saved,saved);$('#place-form').onsubmit=async e=>{e.preventDefault();const q=$('#place-keyword').value.trim();if(!q)return;$('#place-message').textContent='장소를 찾고 있습니다…';try{const params=new URLSearchParams({q,limit:'15'});const data=await fetchJSON('https://photon.komoot.io/api/?'+params);if(!$('#place-results'))return;searchResults=(data.features||[]).filter(x=>Array.isArray(x.geometry?.coordinates)&&x.properties?.name).map(x=>{const p=x.properties,[lng,lat]=x.geometry.coordinates;return{title:p.name,lat,lng,address:[p.country,p.state,p.city,p.district,p.street,p.housenumber].filter(Boolean).join(' '),area:p.city||p.state||'',kind:p.osm_value==='restaurant'?'식당':p.osm_value==='cafe'?'카페':'볼거리',search:true};}).filter(x=>Number.isFinite(x.lat)&&Number.isFinite(x.lng));$('#place-message').textContent=searchResults.length?`${searchResults.length}곳을 찾았습니다. 지도 핀 또는 아래 항목을 선택하세요.`:'검색 결과가 없습니다. 지역과 장소명을 함께 검색하거나 지도에서 위치를 직접 찍어주세요.';mapCtl?.setData([...saved,...searchResults],saved);if(searchResults[0])mapCtl?.go(searchResults[0].lat,searchResults[0].lng,13);$('#place-results').innerHTML=searchResults.map((p,i)=>`<div class="search-result"><h3>${esc(p.title)}</h3><p>${esc(p.address)}</p><button class="btn compact" type="button" data-place-index="${i}">지도에서 선택</button></div>`).join('');$('#place-results').onclick=e=>{const b=e.target.closest('[data-place-index]');if(!b)return;const p=searchResults[Number(b.dataset.placeIndex)];mapCtl?.go(p.lat,p.lng,15);choose(p);};}catch(err){if($('#place-message'))$('#place-message').textContent='검색에 연결하지 못했습니다. 장소 이름을 직접 입력하는 일정 추가는 계속 사용할 수 있습니다. '+errorMessage(err);}};}
async function action(name,el){const t=trip(),id=el?.dataset.id;
 if(name==='new')return editTrip(true);if(name==='close')return closeModal();if(name==='edit-trip')return editTrip(false);if(name==='select-day'){chosenDate=el.dataset.date;return render();}if(name==='route-mode'){routeMode=routeMode==='places'?'areas':'places';return render();}if(name==='add-item')return editItem();if(name==='edit-item')return editItem(id);if(name==='cover')return coverDialog();if(name==='image-search')return imageSearch();if(name==='map')return mapEditor();if(name==='record')return recordEditor(null,el?.dataset.date||chosenDate,el?.dataset.place||'');if(name==='edit-record')return recordEditor(id);if(name==='preview')return previewReport();if(name==='print')return previewReport(true);if(name==='print-current')return printCurrent();if(name==='backup')return backup();if(name==='restore'){$('#backup-input').click();return;}if(name==='old-site')return openLink('https://yeohaengdam.choiseungil.chatgpt.site');
 if(name==='remove-draft-photo'){recordDraftPhotos=recordDraftPhotos.filter(a=>a!==id);dirtyForm=true;renderDraftPhotos();return;}if(name==='view-photo'){const p=photo(id);if(p)modal('여행 사진',`<img src="${p.data}" alt="여행 기록 사진" style="display:block;width:100%;height:auto;border-radius:14px">${attribution(p)}`);return;}
 if(name==='open-trip'){await commit(s=>{s.currentId=id;});chosenDate=trip().startDate;navigate('main');return;}
 if(name==='trash-trip'){if(!window.confirm('이 여행을 휴지통으로 옮길까요? 여행목록에서 다시 복원할 수 있습니다.'))return;await commit(s=>{s.trips.find(x=>x.id===id).deletedAt=new Date().toISOString();if(s.currentId===id)s.currentId=s.trips.find(x=>!x.deletedAt)?.id||null;});render();notify('휴지통으로 옮겼습니다. 필요하면 복원하세요.');return;}
 if(name==='restore-trip'){await commit(s=>{s.trips.find(x=>x.id===id).deletedAt=null;});render();notify('여행을 복원했습니다.');return;}
 if(!t)return;
 if(name==='remove-cover'){await commit(s=>{s.trips.find(x=>x.id===t.id).coverId=null;});closeModal(true);render();return;}
 if(name==='delete-item'){if(!window.confirm('이 일정을 삭제할까요? 연결된 사진 기록은 남겨둡니다.'))return;await commit(s=>{const live=s.trips.find(x=>x.id===t.id);live.itinerary=live.itinerary.filter(x=>x.id!==id);for(const r of live.records)if(r.placeId===id)r.placeId='';});closeModal(true);render();notify('일정을 삭제했습니다.');return;}
 if(name==='delete-record'){if(!window.confirm('이 기록을 삭제할까요? 원래 휴대폰 사진은 삭제되지 않습니다.'))return;await commit(s=>{const live=s.trips.find(x=>x.id===t.id);live.records=live.records.filter(x=>x.id!==id);});closeModal(true);render();return;}
 if(name==='arrive'||name==='done'){await commit(s=>{const x=s.trips.find(a=>a.id===t.id).itinerary.find(a=>a.id===id);x.status=name==='arrive'?'active':'done';if(name==='arrive')x.actualStart=timeNow();else x.actualEnd=timeNow();});render();notify(name==='arrive'?'실제 도착 시간을 저장했습니다.':'완료 시간과 상태를 저장했습니다.');return;}
 if(name==='move-up'||name==='move-down'){await commit(s=>{const live=s.trips.find(a=>a.id===t.id),arr=itemsOn(live,chosenDate),i=arr.findIndex(a=>a.id===id),j=i+(name==='move-up'?-1:1);if(i<0||j<0||j>=arr.length)return;[arr[i],arr[j]]=[arr[j],arr[i]];arr.forEach((x,k)=>{x.order=k;});});render();return;}
 if(name==='directions'){const x=t.itinerary.find(a=>a.id===id);if(x)openLink('https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(Number.isFinite(x.lat)&&Number.isFinite(x.lng)?`${x.lat},${x.lng}`:(x.address||x.title)));return;}
}
window.YD={notify,back(){if($('#modal-root').children.length){closeModal();return;}if(view!=='main'){navigate('main');return;}if(isNative){if(window.confirm('여행담을 종료할까요? 저장한 기록은 그대로 유지됩니다.'))native('YD_EXIT');}},pause(){},printReady(){},debugState:()=>clone(state),debugReport:()=>printDocument(),validateBackup:cleanBackup};
document.addEventListener('click',e=>{const link=e.target.closest('a[href]');if(link){e.preventDefault();openLink(link.href);return;}const btn=e.target.closest('[data-go],[data-action]');if(!btn||btn.disabled)return;if(btn.dataset.go){navigate(btn.dataset.go,btn.dataset.date);return;}Promise.resolve(action(btn.dataset.action,btn)).catch(err=>notify(errorMessage(err)));});
$('#new-trip').onclick=()=>editTrip(true);$('#trip-select').onchange=async e=>{const id=e.target.value;await commit(s=>{s.currentId=id;});chosenDate=trip()?.startDate||todayISO();render();};$('#backup-input').onchange=e=>{const f=e.target.files[0];e.target.value='';restoreFile(f);};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal-root').children.length){e.preventDefault();closeModal();}});
try{db=await openDB();const stored=await dbGet('kv','state');if(stored){if(stored.schema!==1||!Array.isArray(stored.trips))throw new Error('저장 데이터의 형식을 확인할 수 없습니다. 앱 데이터를 지우지 말고 백업 파일을 확인해 주세요.');state=stored;}photoMap=new Map((await dbAll('photos')).map(p=>[p.id,p]));if(!trip())state.currentId=state.trips.find(x=>!x.deletedAt)?.id||null;chosenDate=trip()?.startDate||todayISO();await render();if(!isNative)$('#edition').textContent='브라우저 실행판 · 앱과 별도 저장 · 1.0.0';}catch(err){$('#view').innerHTML=`<div class="empty"><h2>저장소를 열지 못했습니다.</h2><p>${esc(errorMessage(err))}</p><p>기존 데이터를 삭제하거나 초기화하지 말고 오류 내용을 확인해 주세요.</p></div>`;$('#new-trip').disabled=true;}
